def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    guaranteed_units = int(supply / WATER_REQ)
    high_supply = supply >= 24
    medium_high_supply = supply >= 20

    prev_bids = []
    named_prev = {}
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            named_prev[oid] = float(bid)

    bob_bid = named_prev.get('Bob', 0.0)
    cindy_bid = named_prev.get('Cindy', 0.0)
    max_prev = max(prev_bids) if prev_bids else 0.0

    urgent = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    if not alive:
        return float(min(budget, 20.0))

    if guaranteed_units <= 1:
        if urgent:
            bid = max(96.0, bob_bid + 3.0)
            if cindy_bid > 0:
                bid = min(bid, cindy_bid - 1.0)
            bid = max(bid, 92.0)
            return float(min(budget, bid))
        if pressured and medium_high_supply:
            bid = max(88.0, bob_bid + 2.0)
            return float(min(budget, bid))
        return float(min(budget, 8.0))

    if high_supply:
        if urgent:
            bid = max(95.0, bob_bid + 2.5)
            return float(min(budget, bid))
        if pressured:
            bid = max(91.0, bob_bid + 1.5)
            return float(min(budget, bid))
        if bob_bid > 0:
            bid = max(84.0, min(94.0, bob_bid + 1.0))
            return float(min(budget, bid))
        return float(min(budget, 82.0))

    if pressured:
        bid = max(90.0, bob_bid + 2.0)
        return float(min(budget, bid))

    if max_prev >= 120.0:
        return float(min(budget, 18.0))
    return float(min(budget, 12.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append(o)

    # If no opponents alive, spend enough to secure water.
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.6))

    # Read yesterday bids from immediate previous_trace.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Establish a target band based on observed behavior.
    # Cindy averaged ~124 and max ~142; Alex avg ~118 and max ~145.
    # We aim to outbid Alex-ish but stay under Cindy-ish.
    base_target_low = 115.0
    base_target_high = 138.0

    # Compute a pressure signal: how many days without water I have.
    pressure = 0
    if my_no_water_days is not None:
        try:
            pressure = int(my_no_water_days)
        except Exception:
            pressure = 0

    # If my HP is critical or I've already missed water, increase bid.
    if my_hp <= 2 or pressure >= 2:
        target = base_target_high
    elif my_hp <= 3 or pressure == 1:
        target = (base_target_low + base_target_high) / 2.0
    else:
        target = base_target_low

    # If yesterday we saw a high bid, slightly overcut it when possible.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If opponent(s) were bidding aggressively yesterday, we need a bit more.
        if highest_prev_bid >= 130.0:
            target = max(target, min(highest_prev_bid + 2.0, base_target_high))
        else:
            # Otherwise, ensure we beat the likely median clearing level.
            target = max(target, min(sorted(prev_bids)[len(prev_bids) // 2] + 2.0, base_target_high))

    # Convert target to a feasible bid given budget.
    # Also add a small supply-aware adjustment: higher supply should allow less aggressive bids.
    try:
        supply_val = float(supply)
    except Exception:
        supply_val = (MIN_SUPPLY + MAX_SUPPLY) / 2.0

    # When supply is near max, we can shade down slightly.
    if supply_val >= 22.0:
        target *= 0.96
    elif supply_val <= 17.0:
        target *= 1.03

    bid = float(target)

    # Never exceed budget; keep non-negative.
    if my_budget is None:
        return 0.0
    if my_budget <= 0:
        return 0.0

    if bid > my_budget:
        bid = my_budget

    # If budget is extremely low, bid just enough not to waste.
    if my_budget < DAILY_SALARY * 0.2:
        bid = min(my_budget, DAILY_SALARY * 0.15)

    # Final clamp.
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], DAILY_SALARY * 1.2)
    elif day_context['supply'] < 18:
        bid = min(my_status['budget'], max(avg_bid * 1.1, 75))
    else:
        bid = min(my_status['budget'], max(avg_bid * 0.9, 50))

    return float(bid)
